contracts/ProjectStorage.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

contract ProjectRegistry {
    struct ProjectTransaction {
        string projectName;
        uint256 totalRetiredUnits;
        uint256 totalAvailableUnits;
        string status;
        uint256 timestamp;
        string txHash;
    }

    mapping(string => ProjectTransaction[]) private projectHistory;
    string[] private allIds;

    event ProjectUpdated(
        string mongoId,
        string projectName,
        uint256 totalRetiredUnits,
        uint256 totalAvailableUnits,
        string status,
        uint256 timestamp
    );

    function addProjectTransaction(
        string memory _mongoId,
        string memory _projectName,
        uint256 _totalRetiredUnits,
        uint256 _totalAvailableUnits,
        string memory _status
    ) public {
        // If project is new, add its id to allIds array
        if (projectHistory[_mongoId].length == 0) {
            allIds.push(_mongoId);
        }

        ProjectTransaction memory newTx = ProjectTransaction({
            projectName: _projectName,
            totalRetiredUnits: _totalRetiredUnits,
            totalAvailableUnits: _totalAvailableUnits,
            status: _status,
            timestamp: block.timestamp,
            txHash: ""
        });

        projectHistory[_mongoId].push(newTx);

        emit ProjectUpdated(
            _mongoId,
            _projectName,
            _totalRetiredUnits,
            _totalAvailableUnits,
            _status,
            block.timestamp
        );
    }

    function getLatestProject(string memory _mongoId)
        public
        view
        returns (ProjectTransaction memory)
    {
        require(projectHistory[_mongoId].length > 0, "Project not found");
        return projectHistory[_mongoId][projectHistory[_mongoId].length - 1];
    }

    function getProjectHistory(string memory _mongoId)
        public
        view
        returns (ProjectTransaction[] memory)
    {
        return projectHistory[_mongoId];
    }

    function getAllProjectIds() public view returns (string[] memory) {
        return allIds;
    }

    function setTxHash(string memory _mongoId, string memory _txHash) public {
        require(projectHistory[_mongoId].length > 0, "Project not found");
        projectHistory[_mongoId][projectHistory[_mongoId].length - 1].txHash = _txHash;
    }
}

